#!/usr/bin/env bun

// Regenerates src/api/generated.ts from openapi.yaml with @effect/openapi-generator.
// Do not edit the generated file by hand.

import { OpenApiGenerator, layerTransformerSchema } from "@effect/openapi-generator/OpenApiGenerator"
import { Effect } from "effect"
import type { OpenApi } from "effect/http-api"
import path from "node:path"
import { fileURLToPath } from "node:url"

const dir = path.resolve(fileURLToPath(new URL("..", import.meta.url)))
const specPath = path.join(dir, "openapi.yaml")
const outPath = path.join(dir, "src", "api", "generated.ts")

const program = Effect.gen(function* () {
  const spec = Bun.YAML.parse(yield* Effect.promise(() => Bun.file(specPath).text())) as OpenApi.OpenAPISpec
  const generator = yield* OpenApiGenerator
  const source = yield* generator.generate(spec, {
    name: "Multica",
    format: "httpclient",
    onWarning: (warning) => {
      const context = [warning.method?.toUpperCase(), warning.path, warning.operationId].filter(Boolean).join(" ")
      console.error(`WARNING [${warning.code}] ${context}: ${warning.message}`)
    },
  })
  const header = `// Generated by script/generate.ts from openapi.yaml. Do not edit.\n// oxlint-disable\n`
  const adapted = source.replace(
    `import type * as HttpClient from "effect/unstable/http/HttpClient"\nimport * as HttpClientError from "effect/unstable/http/HttpClientError"\nimport * as HttpClientRequest from "effect/unstable/http/HttpClientRequest"\nimport * as HttpClientResponse from "effect/unstable/http/HttpClientResponse"`,
    `import { HttpClient, HttpClientError, HttpClientRequest, HttpClientResponse } from "effect/http"`,
  )
  yield* Effect.promise(() => Bun.write(outPath, `${header}${adapted}`))
  console.log(`wrote ${path.relative(dir, outPath)}`)
})

await Effect.runPromise(program.pipe(Effect.provide(layerTransformerSchema)))
